-- Category-specific project briefs for customers and scope expectations
-- for freelancers. Applies only to the new marketplace-* specialization rows.
-- First-party packages and all historic orders remain unchanged.
BEGIN;
UPDATE services s
SET client_guidance='حتى نعرف المطلوب في '||s.name_ar||'، وضّح: '||v.client_prompt,
    freelancer_guidance='عند تقديم عرض على '||s.name_ar||'، اذكر: '||v.freelancer_prompt
FROM categories c,
 (VALUES
  ('web','هدف الموقع، عدد الصفحات، اللغة، أمثلة التصميم، والنطاق أو الاستضافة إن وجدا','روابط أعمال مشابهة، التقنية المقترحة، عدد الصفحات، مدة التنفيذ والاختبارات'),
  ('mobile','أجهزة التشغيل، الشاشات الأساسية، وظائف المستخدم، ربط الخادم، وحساب المطور إن وجد','خبرة المنصة المطلوبة، تصور الواجهات، خطوات الاختبار ونوع ملف التسليم'),
  ('ecommerce','منصة المتجر، عدد المنتجات، طرق الشحن، الصفحات، التكاملات والهوية','متاجر سابقة، المنصة والإضافات المطلوبة، خطة تجربة الطلب والدعم'),
  ('software','المستخدمون والصلاحيات، التقارير، قواعد البيانات، التكاملات والمتطلبات الحالية','التقنية المقترحة، بنية النظام، الأمن، أسلوب الاختبار والتوثيق'),
  ('uiux','نوع المستخدم، عدد الشاشات، الهوية، الأمثلة المرجعية والنتيجة المرغوبة','ملف الأعمال، أداة التصميم، عدد النماذج وجولات المراجعة'),
  ('branding','اسم النشاط، الجمهور، الألوان المرغوبة، المراجع وملفات التسليم','اتجاهات التصميم والملفات النهائية وعدد المقترحات والتعديلات'),
  ('marketing','الجمهور والمنتج والهدف والقنوات والميزانية الإعلانية التي يديرها العميل','الخطة، التقارير المتوقعة، مؤشرات القياس وحدود إدارة الحسابات'),
  ('social','المنصات، الجمهور، نمط العلامة، عدد المنشورات وجدول النشر','أمثلة المحتوى، آلية الاعتماد والجدولة والمقاييس'),
  ('seo','رابط الموقع واللغة والسوق المستهدف والصفحات والكلمات الرئيسية','التدقيق التقني، الأولويات وطريقة قياس التحسن دون ضمان ترتيب'),
  ('security','إثبات ملكية النظام، النطاق المصرح، بيئة الاختبار ونوع التقرير المطلوب','نطاق التفويض المكتوب، خطة فحص دفاعية وتوثيق المخاطر والإصلاح'),
  ('cloud','مزود الاستضافة والحسابات المتاحة، التطبيق، قواعد البيانات والميزانية','خطة نشر وتراجع ونسخ احتياطية وفحص صحة بعد النشر'),
  ('automation','النظام المرسل والمستقبل، المدخلات والمخرجات، تكرار المهمة والصلاحيات','مخطط سير العمل، آلية معالجة الأخطاء والتجارب والتوثيق'),
  ('analytics','مصادر البيانات وصيغتها، المؤشرات، الفترة الزمنية وأمثلة النتيجة','طريقة تنظيف البيانات، المقاييس، صيغ التسليم والتحقق من النتائج'),
  ('education','المستوى الحالي، الموضوع، عدد الجلسات، اللغة وطريقة الشرح','المؤهلات، خطة الدروس والمحتوى والتقييم والوقت'),
  ('architecture','نوع العقار، المقاسات والمخططات القائمة وهدف العمل','المؤهلات المهنية، الصيغ والاشتراطات وحدود الاعتماد الرسمي'),
  ('interior','قياسات المكان، صورته، الاستخدام، الميزانية والأسلوب المفضل','أمثلة أعمال، قائمة الأثاث، التوزيع والمخططات المطلوبة'),
  ('photo','صور المصدر، عدد الصور، الدقة، الخلفية وتنسيق التسليم','عينات قبل وبعد، طريقة المعالجة والملفات النهائية'),
  ('audio','مدة التسجيل، جودة الصوت، اللغة، النص وحقوق الاستخدام','عينات صوتية وخطوات المعالجة وصيغ التسليم والتعديل'),
  ('video','مدة الفيديو، المقاس، المواد الخام، الجمهور والأسلوب المرجعي','أمثلة مونتاج وخطة العمل والتراخيص وصيغ الفيديو النهائية'),
  ('translation','اللغة الأصلية والمستهدفة، عدد الكلمات، موضوع النص ودرجة التخصص','اللغات التي تتقنها، عينات ترجمة وآلية المراجعة والمصطلحات'),
  ('writing','موضوع المحتوى، الجمهور، اللغة، عدد الكلمات، النبرة والمراجع','نماذج نصوص، بنية المحتوى وآلية التوثيق والمراجعات'),
  ('research','سؤال البحث، الفترة الزمنية، نوع المصادر، نطاق الدول وشكل التقرير','منهج البحث، المصادر، طريقة التحقق من النتائج والتسليم'),
  ('admin_support','المهام اليومية، الأدوات، ساعات العمل، الوصول المسموح وآلية السرية','الخبرة بالبرامج، أوقات التوفر وطريقة التقارير وحماية البيانات'),
  ('sales','المنتج، العملاء المستهدفون، السوق، أهداف العمل ونظام CRM','آلية المتابعة، المخرجات والتقارير والالتزام بعدم الإزعاج'),
  ('customer_support','القنوات، ساعات الدعم، أنواع الاستفسارات، السياسات وأداة التذاكر','أمثلة ردود، مستويات التصعيد ومؤشرات جودة الخدمة'),
  ('hr','نوع الوظيفة، عدد المرشحين أو الموظفين، سياسة الخصوصية والمخرجات','خبرة الموارد البشرية، النماذج والمراحل وكيفية التعامل مع بيانات المرشحين'),
  ('accounting','نوع النشاط، الفترة، ملفات مالية منقحة والمخرج المحاسبي المطلوب','المؤهلات المهنية وحدود الخدمة وتأكيد حماية المعلومات المالية'),
  ('legal','الولاية القضائية ونوع المستند والغاية والوثائق التي يسمح بمراجعتها','الترخيص والخبرة النظامية المناسبة وحدود الرأي المهني والتوثيق'),
  ('business','طبيعة النشاط، العملاء، أهداف المشروع، الميزانية، المنافسون والموعد','الخبرة القطاعية والمنهج والمخرجات والمخاطر والافتراضات'),
  ('files','نوع الملف وعدد الصفحات، القالب المطلوب والصيغة النهائية','نماذج التنسيق، أدوات التحرير وضمان سلامة الجداول والملفات'),
  ('excel','عينة بيانات، عدد الصفوف، المعادلات والمخططات المطلوبة','أسلوب الصيغ، أمثلة لوحات البيانات وطريقة التحقق والتسليم'),
  ('design','المقاسات، نوع المنشور، النصوص، هوية العلامة والمراجع البصرية','نماذج التصميم، عدد الخيارات والتعديلات والملفات المطلوبة'),
  ('ai','مصادر البيانات المصرح بها، المهمة المطلوب أتمتتها، مراجعة الإجابات وخصوصية المستخدم','النماذج والأدوات، التكلفة المتوقعة، ضبط الأخطاء والاختبار البشري'),
  ('operations','خطوات العمل الحالية، الأدوار، المشكلة والمؤشر المراد تحسينه','خطة توثيق العملية، المخاطر ومؤشرات نجاح التغيير'),
  ('other','نوع الخدمة عن بُعد، الهدف، أمثلة العمل والملفات المطلوبة','الخبرة المطابقة والنطاق والمخرجات والمدة والتعديلات')
 ) AS v(category_slug,client_prompt,freelancer_prompt)
WHERE s.category_id=c.id AND c.slug=v.category_slug AND s.slug LIKE 'market-%';
COMMIT;
